package com.smarthub.plus;

import android.content.*;
import android.os.Bundle;
import android.provider.Settings;
import android.widget.*;

/** Opens the real vendor controls; tuning/database edits remain owned by their UI. */
public final class ReceiverToolsActivity extends HubActivity {
    @Override public void onCreate(Bundle s){super.onCreate(s);LinearLayout body=page(tx("الرسيفر والبحث","Receiver and scanning"));LinearLayout directory=card(body);directory.addView(text(tx("البث في IRAQhub","IRAQhub broadcast"),22,true));action(directory,tx("قائمة وظائف Aurum الكاملة: Fast/Manual/USALS/PVR","All Aurum functions: Scan / USALS / PVR"),()->startActivity(new Intent(this,OemFullSettingsActivity.class)));action(directory,tx("مركز CHMAX السحابي وEPG","CHMAX cloud and EPG controls"),()->startActivity(new Intent(this,ChmaxControlCenterActivity.class)));action(directory,tx("تكامل Aurum الكامل · التشخيص والصلاحيات","Aurum integration · routes and diagnostics"),()->startActivity(new Intent(this,OemDvbIntegrationActivity.class)));action(directory,tx("اختبار ريموت DVB · CH/INFO/MENU","DVB remote tester · CH/INFO/MENU"),()->startActivity(new Intent(this,RemoteKeyDiagnosticsActivity.class)));action(directory,tx("الأقمار والترددات","Satellites and transponders"),()->startActivity(new Intent(this,SatelliteBrowserActivity.class)));action(directory,tx("قنواتي والمفضلة","My channels and favourites"),()->startActivity(new Intent(this,ReceiverChannelsActivity.class)));action(directory,tx("المشغل الفضائي المستقل","Independent satellite player"),()->startActivity(new Intent(this,DvbPlaybackActivity.class)));note(directory,tx("التشغيل المستقل للقنوات المجانية يعتمد على إعداد LNB المحفوظ لكل قمر. لا يرسل أوامر حركة للموتور. البحث والقنوات المشفرة تبقى ضمن أدوات المصنع.","Independent free-channel playback uses a saved LNB profile per satellite. No motor movement commands are sent. Scanning and encrypted channels remain in manufacturer tools."));action(directory,tx("ضبط الموالف وLNB","Tuner and LNB profiles"),()->startActivity(new Intent(this,TunerSettingsActivity.class)));ManufacturerFeatures.Entry motor=ManufacturerFeatures.find(this,"motor");if(motor!=null&&ManufacturerFeatures.unavailable(this,motor).isEmpty())action(directory,tx("الموتور · DiSEqC / USALS الأصلي","Motor · firmware DiSEqC / USALS"),()->ChannelControls.motor(this));action(directory,tx("معلومات الإشارة المباشرة","Live signal information"),()->startActivity(new Intent(this,SignalInformationActivity.class)));action(directory,tx("صوت الإنترنت للقناة","Channel Internet Audio"),()->startActivity(new Intent(this,IPAudioActivity.class)));LinearLayout nativeBox=card(body);
        action(nativeBox,tx("إدخال شفرة BISS من واجهة المصنع","Enter BISS key in original firmware"),()->{
            ManufacturerFeatures.Entry biss=ManufacturerFeatures.find(this,"patch");
            if(!ManufacturerFeatures.open(this,biss))toast(tx("محرر BISS الأصلي غير متاح","Native BISS editor unavailable"));
        });
        action(nativeBox,tx("Server Settings · CA · Patch ووظائف المصنع","Server Settings · CA · Patch and manufacturer tools"),()->startActivity(new Intent(this,ManufacturerToolsActivity.class)));nativeBox.addView(text(tx("أدوات النظام الخارجية · اختيارية","External system tools · optional"),22,true));
        note(nativeBox,tx("تفتح هذه الأزرار أدوات المصنع الفعلية. اختر منها إدارة القنوات أو الأقمار وLNB والترددات والبحث. البحث الأعمى يتاح فقط إن كانت واجهة المصنع تدعمه.","These buttons open the actual manufacturer controls. Select channel management, satellites, LNB, transponders or scanning there. Blind scan is available only when supported by that interface."));
        nativeAction(nativeBox,tx("إدارة القنوات · الأقمار · LNB · البحث","Channels · satellites · LNB · scanning"),ReceiverNavigation.menu());
        nativeAction(nativeBox,tx("EPG Pro الأصلي","Native EPG Pro"),ReceiverNavigation.guide());nativeAction(nativeBox,tx("واجهة الرسيفر الأصلية","Original receiver home"),ReceiverNavigation.originalHome());
        LinearLayout hub=card(body);action(hub,tx("قائمة القنوات والبحث المحلي","Channel library and local search"),()->startActivity(new Intent(this,ReceiverChannelsActivity.class)));action(hub,tx("تقرير توافق الجهاز ومصادر البيانات","Device compatibility and data sources"),()->startActivity(new Intent(this,CompatibilityActivity.class)));action(hub,tx("استيراد CHL ومصادر الشعارات","Import CHL and logo sources"),()->startActivity(new Intent(this,LogoSourcesActivity.class)));action(hub,tx("مساعد القنوات والترجمة","Companion and subtitles"),()->startActivity(new Intent(this,SatelliteActivity.class)));action(hub,tx("إعدادات Android","Android settings"),()->{try{startActivity(new Intent(Settings.ACTION_SETTINGS));}catch(Exception e){toast(tx("الإعدادات غير متاحة","Settings unavailable"));}});
    }
    private void nativeAction(LinearLayout box,String label,Intent intent){Button b=action(box,label,()->{if(!ReceiverNavigation.open(this,intent))toast(tx("واجهة المصنع غير متاحة أو لا تسمح بالدخول","Manufacturer interface unavailable or access denied"));});boolean available=ReceiverNavigation.available(this,intent);if(!available){b.setText(label+tx(" · غير متاح"," · unavailable"));b.setEnabled(false);}}
}
